-- Synthetic identities only; this file must run exclusively in the disposable database.
begin;
set search_path=extensions,public;
grant usage on schema extensions to authenticated,anon,hsr_worker;
select no_plan();
insert into auth.users(id) values('91000000-0000-0000-0000-000000000001'),('91000000-0000-0000-0000-000000000002');
insert into auth.sessions(id,user_id,not_after) values('91100000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',clock_timestamp()+interval '1 hour');
insert into hsr.organizations(id,name) values('91200000-0000-0000-0000-000000000001','Task test A'),('91200000-0000-0000-0000-000000000002','Task test B');
insert into hsr.memberships values('91200000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001'),('91200000-0000-0000-0000-000000000002','91000000-0000-0000-0000-000000000002');
set local request.jwt.claim.sub='91000000-0000-0000-0000-000000000001';
set local request.jwt.claims='{"sub":"91000000-0000-0000-0000-000000000001","session_id":"91100000-0000-0000-0000-000000000001"}';
create temporary table parent as select * from hsr.create_public_scan('91200000-0000-0000-0000-000000000001',gen_random_uuid(),'https://example.com/','example.com');
update hsr.public_scan_jobs set state='completed',result_text='{}',result_digest=repeat('a',64),result_worker_id=gen_random_uuid() where id=(select job_id from parent);
create temporary table tasks(tag text,body jsonb);
create temporary table claim(body jsonb);
grant select on parent to authenticated,hsr_worker;
grant select,insert on tasks,claim to authenticated,hsr_worker;
set local role anon;
select throws_ok($$select hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('a',64))$$,'42501',null,'AnonymousCannotStartPublicInput');
reset role;
set local role authenticated;
select throws_ok($$select * from hsr.public_tasks$$,'42501',null,'TaskConsumersCannotReadPrivateSessionOrLease');
select throws_ok($$select * from pgmq.q_hsr_public_task_jobs$$,'42501',null,'TaskConsumersCannotReadInputQueue');
select throws_ok($$select hsr.claim_public_task(gen_random_uuid())$$,'42501',null,'TaskConsumersCannotClaimWorkerAuthority');
select throws_ok($$select hsr.create_public_task('91200000-0000-0000-0000-000000000002',(select scan_id from parent),gen_random_uuid(),repeat('a',64))$$,'42501','HSR_SESSION_REQUIRED','TaskAdmissionRequiresCurrentWorkspace');
select throws_ok($$select hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('b',64))$$,'22023','HSR_VERIFIED_PUBLIC_REVIEW_REQUIRED','TaskSourceMustPinCompletedParentDigest');
insert into tasks values('initial',hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),'91300000-0000-0000-0000-000000000001',repeat('a',64)));
select is((select body->>'State' from tasks where tag='initial'),'queued','PublicTaskAdmissionDoesNotClaimExecution');
select is((select body->'Job'->>'ParentScanId' from tasks where tag='initial'),(select scan_id::text from parent),'TaskPreservesExactParentReview');
select is(hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),'91300000-0000-0000-0000-000000000001',repeat('a',64)),(select body from tasks where tag='initial'),'TaskRequestReconciliationKeepsOriginalIdentity');
select ok((select not(body ? 'Token') and not(body ? 'SessionId') and not(body ? 'LeaseToken') from tasks where tag='initial'),'TaskMetadataOmitsPrivateInputCapabilities');
reset role;
set local role hsr_worker;
insert into claim select hsr.claim_public_task('91400000-0000-0000-0000-000000000001');
select is((select body->>'Status' from claim),'Claimed','TaskWorkerClaimsOneDurableJob');
select is(hsr.claim_public_task(gen_random_uuid())->>'Status','AtCapacity','TaskWorkerCannotOverlapInputJobs');
select ok(not hsr.renew_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',null,'Starting'),'NullCapabilityCannotRenewTask');
select ok(not hsr.renew_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),gen_random_uuid(),(select (body->>'Token')::uuid from claim),'Starting'),'ForeignWorkerCannotRenewTask');
select ok(hsr.renew_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),'KeyboardAttempt1'),'CurrentTaskCapabilityRenewsInputPhase');
select ok(not hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),'{}'),'TaskPublicationCannotOmitCleanupAndOriginalVerification');
reset role;
set local role authenticated;
select is(hsr.cancel_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),(select (body->'Job'->>'JobId')::uuid from claim))->>'State','cancelled','TaskCancelRevokesFutureInputAuthority');
reset role;
set local role hsr_worker;
select ok(not hsr.renew_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),'Starting'),'CancelledTaskCannotRegainInputAuthority');
select is(hsr.claim_public_task(gen_random_uuid())->>'Status','Empty','CancelledTaskIsNeverRequeued');
reset role;
set local role authenticated;
insert into tasks values('expire',hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('a',64)));
reset role;
truncate claim;
set local role hsr_worker;
insert into claim select hsr.claim_public_task('91400000-0000-0000-0000-000000000001');
reset role;
update hsr.public_tasks set lease_expires_at=clock_timestamp()-interval '1 second' where state='leased';
set local role hsr_worker;
select is(hsr.claim_public_task(gen_random_uuid())->>'Status','Empty','ExpiredInputAttemptIsNotReexecuted');
reset role;
select is((select state from hsr.public_tasks where id=(select (body->'Job'->>'JobId')::uuid from claim)),'interrupted','ExpiredInputAttemptRetainsInterruptedState');
set local role authenticated;
insert into tasks values('session',hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('a',64)));
reset role;
truncate claim;
set local role hsr_worker;
insert into claim select hsr.claim_public_task('91400000-0000-0000-0000-000000000001');
reset role;
update auth.sessions set not_after=clock_timestamp()-interval '1 second' where id='91100000-0000-0000-0000-000000000001';
set local role hsr_worker;
select ok(not hsr.renew_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),'PointerComparison'),'ExpiredApplicationSessionStopsNewTaskInputs');
reset role;
set local role authenticated;
select throws_ok($$select hsr.read_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent))$$,'42501','HSR_SESSION_REQUIRED','TaskOriginalReadRequiresCurrentApplicationSession');
select throws_ok($$select hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('a',64))$$,'42501','HSR_SESSION_REQUIRED','TaskAdmissionCannotReuseExpiredApplicationSession');
reset role;
-- Restore the synthetic session and finish a distinct one-shot job.
update auth.sessions set not_after=clock_timestamp()+interval '1 hour';
update hsr.public_tasks set state='interrupted',finished_at=clock_timestamp() where state='leased';
set local role authenticated;
insert into tasks values('publish',hsr.create_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent),gen_random_uuid(),repeat('a',64)));
reset role;
truncate claim;
set local role hsr_worker;
insert into claim select hsr.claim_public_task('91400000-0000-0000-0000-000000000001');
reset role;
create temporary table publication as select jsonb_build_object('Schema','hsr-public-task-publication-v1','ParentOriginalSha256',repeat('a',64),'ReportSha256',repeat('c',64),'ReportBytes',4000,'ExecutionId','91500000-0000-0000-0000-000000000001','NativeRemoved',true,'OriginalsVerified',true,'Assessment',jsonb_build_object('Outcome','WebsiteEvidenceReady','Conditions',(select jsonb_agg(jsonb_build_object('Id',x,'Satisfied',true)) from unnest(array['MeaningfulTask','RecordedBarrier','ExactTrigger','AccessibilityContext','RepeatedFailure','PointerComparison','ReproducibleEnvironment','OriginalArtifacts']) x))) as body;
grant select on publication to hsr_worker;
set local role hsr_worker;
select ok(not hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select body-'NativeRemoved' from publication)),'TaskPublicationRequiresNativeRemoval');
select ok(not hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select jsonb_set(body,'{OriginalsVerified}','false') from publication)),'TaskPublicationRequiresOriginalReadback');
select ok(not hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select jsonb_set(body,'{Assessment,Conditions}','[]') from publication)),'TaskPublicationRequiresEightEvidenceConditions');
select ok(not hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select jsonb_set(body,'{Assessment,Conditions,0,Satisfied}','false') from publication)),'TaskReadyPublicationCannotIncludeMissingCondition');
select ok(hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select body from publication)),'TaskOriginalCapabilityPublishesItsBoundReceipt');
select ok(hsr.finish_public_task('91200000-0000-0000-0000-000000000001',(select (body->'Job'->>'JobId')::uuid from claim),'91400000-0000-0000-0000-000000000001',(select (body->>'Token')::uuid from claim),(select body from publication)),'TaskPublicationRetryDoesNotReexecuteInputs');
reset role;
select is((select state from hsr.public_tasks where id=(select (body->'Job'->>'JobId')::uuid from claim)),'completed','TaskPublicationRetainsCompletedOriginalReceipt');
delete from hsr.memberships where organization_id='91200000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select hsr.read_public_task('91200000-0000-0000-0000-000000000001',(select scan_id from parent))$$,'42501','HSR_SESSION_REQUIRED','RevokedMembershipCannotReadCompletedTaskOriginals');
reset role;
select * from finish();
rollback;
